CREATE TABLE social_channels (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), connection_id uuid NOT NULL REFERENCES integration_connections(id), external_id text NOT NULL, service text NOT NULL CHECK (service IN ('instagram','facebook','threads','linkedin','twitter','pinterest','tiktok','youtube','mastodon','bluesky','googlebusiness')), name text NOT NULL, avatar_url text, active boolean NOT NULL DEFAULT true, synced_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX social_channels_connection_external_uidx ON social_channels (connection_id, external_id); CREATE INDEX social_channels_org_service_idx ON social_channels (org_id, service); ALTER TABLE social_channels ENABLE ROW LEVEL SECURITY; CREATE POLICY social_channels_isolation_by_org ON social_channels FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid);
CREATE TABLE social_posts (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), channel_id uuid NOT NULL REFERENCES social_channels(id), connection_id uuid NOT NULL REFERENCES integration_connections(id), created_by uuid NOT NULL REFERENCES users(id), text text NOT NULL, status text NOT NULL CHECK (status IN ('draft','scheduled','publishing','published','failed','cancelled')), publish_mode text NOT NULL CHECK (publish_mode IN ('draft','queue','now','schedule')), scheduled_at timestamptz, published_at timestamptz, external_id text, provider_status text, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX social_posts_org_scheduled_idx ON social_posts (org_id, scheduled_at); CREATE INDEX social_posts_org_status_idx ON social_posts (org_id, status); ALTER TABLE social_posts ENABLE ROW LEVEL SECURITY; CREATE POLICY social_posts_isolation_by_org ON social_posts FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid);
GRANT SELECT, INSERT, UPDATE, DELETE ON social_channels, social_posts TO app_user;
ALTER PUBLICATION electric_publication_default ADD TABLE social_channels, social_posts;
UPDATE permission_groups SET capabilities = capabilities || '["social:read", "social:write"]'::jsonb, updated_at = now() WHERE name IN ('Proprietário','Administrador','Gerente','Agente') AND NOT capabilities @> '["social:read", "social:write"]'::jsonb;
UPDATE permission_groups SET capabilities = capabilities || '["social:read"]'::jsonb, updated_at = now() WHERE name = 'Visualizador' AND NOT capabilities @> '["social:read"]'::jsonb;
